	@Test
	void preservesDuplicateOrderAndSingleLifecycle() throws Exception {
		String json = """
				{"results":{"bindings":[
				{"x":{"type":"literal","value":"first"}},
				{"x":{"type":"literal","value":"first"}},
				{"x":{"type":"literal","value":"last"}}
				]},"head":{"vars":["x"]}}
				""";
		RecordingHandler handler = new RecordingHandler();
		SPARQLResultsJSONParser parser = new SPARQLResultsJSONParser();
		parser.setQueryResultHandler(handler);

		parser.parseQueryResult(new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8)));

		assertEquals(List.of("start:[x]", "row:first", "row:first", "row:last", "end"), handler.events);
	}

