		RecordingHandler handler = new RecordingHandler();
		SPARQLResultsJSONParser parser = new SPARQLResultsJSONParser();
		parser.setQueryResultHandler(handler);
		byte[] bytes = json.getBytes(StandardCharsets.UTF_8);
		int secondRow = json.indexOf("{\"x\":{\"type\":\"literal\",\"value\":\"second\"}}");
		InputStream guarded = new InputStream() {
			private int position;

			@Override
			public int read() throws IOException {
				if (position == secondRow && !handler.events.contains("row:first")) {
					throw new IOException("second row was read before the first callback");
				}
				return position == bytes.length ? -1 : bytes[position++];
			}

			@Override
			public int read(byte[] buffer, int offset, int length) throws IOException {
				int next = read();
				if (next == -1) {
					return -1;
				}
				buffer[offset] = (byte) next;
				return 1;
			}
		};

		parser.parseQueryResult(guarded);

