	@Test
	void streamsManyPreHeadRowsWithoutCollectingThemInTheHandler() throws Exception {
		int rowCount = 20_000;
		byte[] prefix = "{\"results\":{\"bindings\":[".getBytes(StandardCharsets.UTF_8);
		byte[] row = "{\"x\":{\"type\":\"literal\",\"value\":\"same\"}}".getBytes(StandardCharsets.UTF_8);
		byte[] laterRow = ",{\"x\":{\"type\":\"literal\",\"value\":\"same\"}}".getBytes(StandardCharsets.UTF_8);
		byte[] suffix = "]},\"head\":{\"vars\":[\"x\"]}}".getBytes(StandardCharsets.UTF_8);
		Enumeration<InputStream> parts = new Enumeration<>() {
			private int part;

			@Override
			public boolean hasMoreElements() {
				return part <= rowCount + 1;
			}

			@Override
			public InputStream nextElement() {
				int current = part++;
				if (current == 0) {
					return new ByteArrayInputStream(prefix);
				}
				if (current == rowCount + 1) {
					return new ByteArrayInputStream(suffix);
				}
				return new ByteArrayInputStream(current == 1 ? row : laterRow);
			}
		};
		int[] callbacks = new int[3];
		QueryResultCollector handler = new QueryResultCollector() {
			@Override
			public void startQueryResult(List<String> bindingNames) {
				callbacks[0]++;
			}

			@Override
			public void handleSolution(BindingSet bindingSet) {
				callbacks[1]++;
			}

			@Override
			public void endQueryResult() {
				callbacks[2]++;
			}
		};
		SPARQLResultsJSONParser parser = new SPARQLResultsJSONParser();
		parser.setQueryResultHandler(handler);

		parser.parseQueryResult(new SequenceInputStream(parts));

		assertEquals(1, callbacks[0]);
		assertEquals(rowCount, callbacks[1]);
		assertEquals(1, callbacks[2]);
	}

