	@Test
	void concurrentPreHeadParsesShareOneDiskBudget() throws Exception {
		StringBuilder json = new StringBuilder("{\"results\":{\"bindings\":[");
		for (int i = 0; i < 8_000; i++) {
			if (i > 0) {
				json.append(',');
			}
			json.append("{\"x\":{\"type\":\"literal\",\"value\":\"same\"}}");
		}
		json.append("]},\"head\":{\"vars\":[\"x\"]}}");
		byte[] bytes = json.toString().getBytes(StandardCharsets.UTF_8);
		int headStart = json.indexOf(",\"head\"");
		CountDownLatch firstPaused = new CountDownLatch(1);
		CountDownLatch releaseFirst = new CountDownLatch(1);
		InputStream pausedBeforeHead = new InputStream() {
			private int position;

			@Override
			public int read() throws IOException {
				if (position == headStart) {
					firstPaused.countDown();
					try {
						if (!releaseFirst.await(10, TimeUnit.SECONDS)) {
							throw new IOException("timed out while pausing before head");
						}
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new IOException(e);
					}
				}
				return position == bytes.length ? -1 : bytes[position++] & 0xff;
			}

			@Override
			public int read(byte[] buffer, int offset, int length) throws IOException {
				if (length == 0) {
					return 0;
				}
				int next = read();
				if (next == -1) {
					return -1;
				}
				buffer[offset] = (byte) next;
				return 1;
			}
		};
		long budget = 384L * 1024;
		Set<Path> before = preHeadSpoolFiles();
		SPARQLResultsJSONParser firstParser = new SPARQLResultsJSONParser();
		firstParser.set(AbstractSPARQLJSONParser.MAX_PRE_HEAD_BYTES, budget);
		firstParser.setQueryResultHandler(new RecordingHandler());

		try (ExecutorService executor = Executors.newSingleThreadExecutor()) {
			Future<Boolean> first = executor.submit(() -> {
				firstParser.parseQueryResult(pausedBeforeHead);
				return true;
			});
			try {
				assertTrue(firstPaused.await(10, TimeUnit.SECONDS));
				long firstStagedBytes = 0;
				for (Path path : preHeadSpoolFiles()) {
					if (!before.contains(path)) {
						firstStagedBytes += Files.size(path);
					}
				}
				assertTrue(firstStagedBytes > budget / 2,
						"first parser must reserve enough bytes to exercise the cap: " + firstStagedBytes);
				SPARQLResultsJSONParser secondParser = new SPARQLResultsJSONParser();
				secondParser.set(AbstractSPARQLJSONParser.MAX_PRE_HEAD_BYTES, budget);
				secondParser.setQueryResultHandler(new RecordingHandler());
				assertThrows(QueryResultParseException.class,
						() -> secondParser.parseQueryResult(new ByteArrayInputStream(bytes)));
			} finally {
				releaseFirst.countDown();
			}
			assertTrue(first.get());
		}

		SPARQLResultsJSONParser afterRelease = new SPARQLResultsJSONParser();
		afterRelease.set(AbstractSPARQLJSONParser.MAX_PRE_HEAD_BYTES, budget);
		afterRelease.setQueryResultHandler(new RecordingHandler());
		afterRelease.parseQueryResult(new ByteArrayInputStream(bytes));
	}

	@Test
	void releasesReservationEvenWhenSpoolDeletionFails() throws Exception {
		String json = "{\"results\":{\"bindings\":[{\"x\":{\"type\":\"literal\",\"value\":\""
				+ "x".repeat(256) + "\"}}]},\"head\":{\"vars\":[\"x\"]}}";
		byte[] bytes = json.getBytes(StandardCharsets.UTF_8);
		Set<Path> before = preHeadSpoolFiles();
		CountDownLatch started = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		SPARQLResultsJSONParser firstParser = new SPARQLResultsJSONParser();
		firstParser.set(AbstractSPARQLJSONParser.MAX_PRE_HEAD_BYTES, 512L);
		firstParser.setQueryResultHandler(new QueryResultCollector() {
			@Override
			public void startQueryResult(List<String> bindingNames) {
				started.countDown();
				try {
					if (!release.await(10, TimeUnit.SECONDS)) {
						throw new IllegalStateException("timed out waiting to release the first parser");
					}
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new IllegalStateException(e);
				}
			}
		});

		Path obstructed = null;
		try (ExecutorService executor = Executors.newSingleThreadExecutor()) {
			Future<?> first = executor.submit(() -> {
				firstParser.parseQueryResult(new ByteArrayInputStream(bytes));
				return null;
			});
			try {
				assertTrue(started.await(10, TimeUnit.SECONDS));
				List<Path> created = preHeadSpoolFiles().stream().filter(path -> !before.contains(path)).toList();
				assertEquals(1, created.size());
				obstructed = created.get(0);
				assertTrue(Files.size(obstructed) > 256);
				Files.delete(obstructed);
				Files.createDirectory(obstructed);
				Files.writeString(obstructed.resolve("keep"), "keep");
			} finally {
				release.countDown();
			}
			assertThrows(ExecutionException.class, first::get);

			SPARQLResultsJSONParser secondParser = new SPARQLResultsJSONParser();
			secondParser.set(AbstractSPARQLJSONParser.MAX_PRE_HEAD_BYTES, 512L);
			secondParser.setQueryResultHandler(new RecordingHandler());
			secondParser.parseQueryResult(new ByteArrayInputStream(bytes));
		} finally {
			if (obstructed != null && Files.isDirectory(obstructed)) {
				Files.deleteIfExists(obstructed.resolve("keep"));
			}
			if (obstructed != null) {
				Files.deleteIfExists(obstructed);
			}
		}
	}

	private static Set<Path> preHeadSpoolFiles() throws IOException {
		Path probe = Files.createTempFile("rdf4j-sparql-json-test-probe-", ".tmp");
		Path directory = probe.getParent();
		Files.delete(probe);
		try (var paths = Files.list(directory)) {
			return paths.filter(path -> path.getFileName().toString().startsWith("rdf4j-sparql-json-prehead-"))
					.collect(Collectors.toSet());
		}
	}

	private static final class RecordingHandler extends QueryResultCollector {

		private final List<String> events = new ArrayList<>();
		private final List<BindingSet> rows = new ArrayList<>();

		@Override
		public void startQueryResult(List<String> bindingNames) {
			events.add("start:" + bindingNames);
		}

		@Override
		public void handleSolution(BindingSet bindingSet) {
			rows.add(bindingSet);
			events.add("row:" + bindingSet.getValue("x").stringValue());
		}

		@Override
		public void endQueryResult() {
			events.add("end");
		}
	}
